import type { WorkspaceSnapshot } from '@moss/contracts';
import type { SqliteWorkspaceRepository } from './repository.js';

export interface LegacyImportOptions {
  /**
   * Preserve legacy IDs when they are already stable strings. IDs generated by
   * the browser for joins are mapped consistently across all entity families.
   */
  preserveIds?: boolean;
}

export interface LegacyImportResult {
  snapshot: WorkspaceSnapshot;
  projectIds: Record<string, string>;
  taskIds: Record<string, string>;
}

function createLegacyId(kind: string, index: number): string {
  return `legacy-${kind}-${String(index + 1).padStart(6, '0')}`;
}

function mapValue(value: string | null | undefined, ids: Map<string, string>): string | null {
  if (!value) return null;
  return ids.get(value) ?? value;
}

/**
 * Imports the old browser snapshot without assuming that legacy IDs are valid
 * ULIDs. Relations are remapped in one repository transaction by replaceSnapshot.
 */
export function importLegacySnapshot(
  snapshot: WorkspaceSnapshot,
  repository: SqliteWorkspaceRepository,
  { preserveIds = false }: LegacyImportOptions = {},
): LegacyImportResult {
  const projectIds = new Map<string, string>();
  const taskIds = new Map<string, string>();
  const memberIds = new Map<string, string>();
  const fileIds = new Map<string, string>();
  const commentIds = new Map<string, string>();
  const viewIds = new Map<string, string>();

  snapshot.members.forEach((member, index) => {
    memberIds.set(member.id, preserveIds ? member.id : createLegacyId('member', index));
  });
  snapshot.projects.forEach((project, index) => {
    projectIds.set(project.id, preserveIds ? project.id : createLegacyId('project', index));
  });
  snapshot.tasks.forEach((task, index) => {
    taskIds.set(task.id, preserveIds ? task.id : createLegacyId('task', index));
  });
  snapshot.files.forEach((file, index) => {
    fileIds.set(file.id, preserveIds ? file.id : createLegacyId('file', index));
  });
  snapshot.comments.forEach((comment, index) => {
    commentIds.set(comment.id, preserveIds ? comment.id : createLegacyId('comment', index));
  });
  snapshot.savedViews.forEach((view, index) => {
    viewIds.set(view.id, preserveIds ? view.id : createLegacyId('view', index));
  });

  const imported: WorkspaceSnapshot = {
    ...structuredClone(snapshot),
    me: mapValue(snapshot.me, memberIds) ?? snapshot.me,
    members: snapshot.members.map(member => ({
      ...member,
      id: memberIds.get(member.id) ?? member.id,
    })),
    projects: snapshot.projects.map(project => ({
      ...project,
      id: projectIds.get(project.id) ?? project.id,
      lead: mapValue(project.lead, memberIds) ?? project.lead,
      members: project.members.map(member => mapValue(member, memberIds) ?? member),
    })),
    tasks: snapshot.tasks.map(task => ({
      ...task,
      id: taskIds.get(task.id) ?? task.id,
      project: mapValue(task.project, projectIds) ?? task.project,
      assignee: mapValue(task.assignee, memberIds),
      deps: task.deps.map(id => mapValue(id, taskIds) ?? id),
      subtasks: task.subtasks.map(subtask => ({
        ...subtask,
        assignee: mapValue(subtask.assignee, memberIds),
      })),
      attachments: task.attachments.map(attachment => ({
        ...attachment,
        id: mapValue(attachment.id, fileIds) ?? attachment.id,
        by: mapValue(attachment.by, memberIds),
      })),
    })),
    comments: snapshot.comments.map(comment => ({
      ...comment,
      id: commentIds.get(comment.id) ?? comment.id,
      task: mapValue(comment.task, taskIds) ?? comment.task,
      by: mapValue(comment.by, memberIds) ?? comment.by,
      re: Object.fromEntries(Object.entries(comment.re).map(([reaction, members]) => [reaction, members.map(id => mapValue(id, memberIds) ?? id)])),
    })),
    activity: snapshot.activity.map(entry => ({
      ...entry,
      by: mapValue(entry.by, memberIds),
      task: mapValue(entry.task, taskIds),
      project: mapValue(entry.project, projectIds),
    })),
    files: snapshot.files.map(file => ({
      ...file,
      id: fileIds.get(file.id) ?? file.id,
      project: mapValue(file.project, projectIds) ?? file.project,
      task: mapValue(file.task, taskIds),
      by: mapValue(file.by, memberIds),
    })),
    savedViews: snapshot.savedViews.map(view => ({
      ...view,
      id: viewIds.get(view.id) ?? view.id,
      project: mapValue(view.project, projectIds) ?? view.project,
    })),
    projOrder: snapshot.projOrder.map(id => mapValue(id, projectIds) ?? id),
  };

  repository.replaceSnapshot(imported);

  return {
    snapshot: imported,
    projectIds: Object.fromEntries(projectIds),
    taskIds: Object.fromEntries(taskIds),
  };
}
